# Configuration for Groq Whisper

To use this STT service in bot.py, replace the STT initialization with:

from pipecat.services.groq.stt import GroqSTTService

stt = GroqSTTService(
    api_key=os.getenv("API_KEY"),  # Use appropriate env var
    **{
    "model": "whisper-large-v3"
}
)
